    // In ASP.NET Core, action methods return IActionResult.
    // No need for Response.Clear/Write/End — just return a file result.
    [HttpPost]
    public IActionResult Export()
    {
        var data = GenerateReport();
        var bytes = Encoding.UTF8.GetBytes(data);
        return File(bytes, "text/csv", "report.csv");
    }

    // === Redirect: Response.Redirect(url, true) → return RedirectResult ===
    // Response.Redirect(url, true) called Thread.Abort to halt execution.
    // In ASP.NET Core, returning a redirect result ends the action naturally.
    // The ThreadAbortException catch block is removed entirely.
    [HttpPost]
    public IActionResult ProcessAction()
    {
        if (!User.Identity?.IsAuthenticated ?? true)
        {
            return Redirect("/login");
        }

        try
        {
            ProcessRequest();
            return Redirect("/success");
        }
        catch (Exception ex)
        {
            LogError(ex);
            return Redirect("/error");
        }
    }

